-- =====================================================================
-- 生产库结构核对脚本（只读）：check_schema_yhny.sql
-- 目的：检查 edop_yhny 库表结构是否与当前代码（HEAD b8a94411）一致
-- 来源：由代码仓 mapper XML 自动提取的 期望表.字段 清单生成
--       （350 张表 / 8970 个字段）
-- 输出：A 段 = 库里缺失的整表（多为未启用模块，属提示性）
--       B 段 = 表存在但缺失的字段（关键差异，会导致 SQL 报错）
--       C 段 = 汇总统计
-- 只读：仅创建 TEMPORARY 表，不修改任何业务数据
-- 执行：双击 check_schema_yhny.bat，或
--       mysql -uroot -p --default-character-set=utf8mb4 edop_yhny < 本文件
-- =====================================================================
DROP TEMPORARY TABLE IF EXISTS expected_cols;
CREATE TEMPORARY TABLE expected_cols (
  table_name  VARCHAR(64) NOT NULL,
  column_name VARCHAR(64) NOT NULL,
  PRIMARY KEY (table_name, column_name)
) ENGINE=MEMORY;


-- =====================================================================
-- A 段：库里缺失的整表（提示性：未启用模块的表属正常）
-- =====================================================================
SELECT e.table_name AS missing_table, COUNT(*) AS expected_cols
FROM expected_cols e
WHERE NOT EXISTS (SELECT 1 FROM information_schema.TABLES t
                  WHERE t.TABLE_SCHEMA = DATABASE() AND t.TABLE_NAME = e.table_name)
GROUP BY e.table_name
ORDER BY e.table_name;

-- =====================================================================
-- B 段：表存在但缺失的字段（关键差异，新 jar 查询会报 Unknown column）
-- =====================================================================
SELECT e.table_name, e.column_name AS missing_column
FROM expected_cols e
WHERE EXISTS (SELECT 1 FROM information_schema.TABLES t
              WHERE t.TABLE_SCHEMA = DATABASE() AND t.TABLE_NAME = e.table_name)
  AND NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS c
                  WHERE c.TABLE_SCHEMA = DATABASE() AND c.TABLE_NAME = e.table_name
                    AND c.COLUMN_NAME = e.column_name)
ORDER BY e.table_name, e.column_name;

-- =====================================================================
-- C 段：汇总统计
-- =====================================================================
SELECT
  (SELECT COUNT(DISTINCT table_name) FROM expected_cols) AS expected_tables,
  (SELECT COUNT(*) FROM expected_cols) AS expected_columns,
  (SELECT COUNT(DISTINCT e.table_name) FROM expected_cols e
   WHERE NOT EXISTS (SELECT 1 FROM information_schema.TABLES t
                     WHERE t.TABLE_SCHEMA = DATABASE() AND t.TABLE_NAME = e.table_name)) AS missing_tables,
  (SELECT COUNT(*) FROM expected_cols e
   WHERE EXISTS (SELECT 1 FROM information_schema.TABLES t
                 WHERE t.TABLE_SCHEMA = DATABASE() AND t.TABLE_NAME = e.table_name)
     AND NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS c
                     WHERE c.TABLE_SCHEMA = DATABASE() AND c.TABLE_NAME = e.table_name
                       AND c.COLUMN_NAME = e.column_name)) AS missing_columns;

DROP TEMPORARY TABLE IF EXISTS expected_cols;
